{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 public access block is missing",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "Although the bucket ACL is private, no account-independent bucket public access block prevents future public ACLs or policies. This could expose financial data if the bucket policy or ACL is later changed."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 versioning is disabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "The financial data bucket has no versioning configuration, so overwritten or deleted objects cannot be reliably recovered."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket does not use KMS default encryption",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The bucket has no explicit default encryption configuration. Financial objects should be encrypted with KMS rather than relying on implicit S3 encryption defaults."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is disabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "No server access logging is configured, limiting the ability to investigate access to financial data. The patch requires a separately secured log destination bucket."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 lifecycle configuration is missing",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The bucket has no lifecycle configuration. A lifecycle rule is added to remove incomplete multipart uploads without expiring retained financial objects."
    },
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 cross-region replication is disabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The bucket has no replication configuration, leaving financial data without the policy-required cross-region copy. The patch configures replication to a caller-supplied destination bucket using a caller-supplied IAM role."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Destructive deletion of the S3 bucket is enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "The explicit force_destroy setting allows Terraform to delete the bucket even when it contains financial records and retained versions. This increases the impact of accidental or unauthorized infrastructure destruction."
    }
  ],
